        'contacts' => ['t' => 'தொடர்புகளைச் சேர்த்து நிர்வகிக்கவும்', 's' => 'வாடிக்கையாளர் பட்டியலை ஒரே இடத்தில் வைத்தால், எப்போது வேண்டுமானாலும் மெசேஜ் அனுப்பலாம்.',
            'steps' => ['<b>Contacts</b>-ஐத் திறந்து <b>+ Add contact</b>-ஐ அழுத்தவும்.', 'பெயரையும் நாட்டுக் குறியீட்டுடன் எண்ணையும் கொடுங்கள், உதா. <b>919876543210</b>.', 'தேடல் அல்லது வடிகட்டி மூலம் கண்டுபிடிக்கவும்; வரிசைகளைத் தேர்ந்தெடுத்து நீக்கலாம் அல்லது குழுவில் சேர்க்கலாம்.', '<b>Export Excel</b> மூலம் பட்டியலைப் பதிவிறக்கலாம்.'],
            'tips' => ['எப்போதும் நாட்டுக் குறியீடு (இந்தியாவுக்கு 91) சேர்க்கவும் — + அல்லது இடைவெளி வேண்டாம்.']],
        'groups' => ['t' => 'தொடர்புகளைக் குழுக்களாகப் பிரிக்கவும்', 's' => 'வாடிக்கையாளர்களைக் குழுவாக்குங்கள் (VIP, சென்னை, புதிய லீட்கள்) — கேம்பெயின் சரியானவர்களுக்குப் போகும்.',
            'steps' => ['<b>Contacts → Groups</b>-ஐத் திறந்து <b>+ New group</b>-ஐ அழுத்தவும்.', 'குழுவுக்குப் பெயர் கொடுத்து <b>Create group</b>-ஐ அழுத்தவும்.', 'Contacts பக்கத்திலிருந்து சேர்க்கவும், அல்லது பட்டியலை நேரடியாகக் குழுவில் <b>Import</b> செய்யவும்.', 'கேம்பெயின் உருவாக்கும்போது இந்தக் குழுவை ஆடியன்ஸாகத் தேர்ந்தெடுக்கவும்.']],
        'bulk-import' => ['t' => 'Excel-இலிருந்து தொடர்புகளை இறக்குமதி செய்யவும்', 's' => 'CSV கோப்பு மூலம் நூற்றுக்கணக்கான தொடர்புகளை ஒரே முறையில் சேர்க்கவும்.',
            'steps' => ['<b>Bulk Contacts</b>-ஐத் திறக்கவும்.', '<b>CSV format</b>-ஐப் பார்த்து மாதிரிக் கோப்பைப் பதிவிறக்கவும்.', 'Excel-இல் பெயர்களையும் எண்களையும் நிரப்பி CSV-ஆகச் சேமிக்கவும்.', '<b>Upload a CSV file</b>-ஐ அழுத்தவும். முடிந்ததும் புதியவை, நகல்கள் எண்ணிக்கை காட்டும்.'],
            'tips' => ['Excel-இல் எண்களை டெக்ஸ்ட் ஆக வைத்தால் முதல் இலக்கங்கள் தொலையாது.']],
        'opt-out' => ['t' => 'ஆப்ட்-அவுட்களை நிர்வகிக்கவும்', 's' => 'வேண்டாம் என்று சொன்னவர்களுக்கு அனுப்பாதீர்கள் — உங்கள் எண்ணின் தரம் பாதுகாக்கப்படும்.',
            'steps' => ['<b>Opt-out Manager</b>-ஐத் திறக்கவும்.', '<b>Add to opt-out list</b>-ஐ அழுத்தி எண்ணை உள்ளிடவும்.', 'ஆப்ட்-அவுட் எண்கள் ஒவ்வொரு கேம்பெயினிலும் தானாகத் தவிர்க்கப்படும்.'],
            'tips' => ['ஆப்ட்-அவுட்களை மதித்தால் Meta-வில் உங்கள் எண்ணின் தர மதிப்பீடு உயர்வாக இருக்கும்.']],
        'qr-code' => ['t' => 'WhatsApp QR குறியீடு பெறவும்', 's' => 'QR குறியீட்டை அச்சிடுங்கள் — வாடிக்கையாளர்கள் ஒரே ஸ்கேனில் உங்களுக்கு மெசேஜ் செய்யலாம்.',
            'steps' => ['<b>WhatsApp QR Code</b>-ஐத் திறக்கவும்.', '<b>Place an order</b> அல்லது <b>Book appointment</b> போன்ற நோக்கத்தைத் தேர்ந்தெடுங்கள் — முதல் மெசேஜ் தானாக நிரம்பும்.', '<b>Customise</b> மூலம் உரையை மாற்றி <b>Preview</b>-ஐப் பாருங்கள்.', 'பதிவிறக்கி கவுண்டர், பில், மெனு அல்லது பேக்கேஜிங்கில் ஒட்டுங்கள்.']],
        'bot-replies' => ['t' => 'தானியங்கி பதில்களை அமைக்கவும்', 's' => 'வாடிக்கையாளர்கள் "price", "hi", "address" போன்றவற்றை அனுப்பியதும் உடனே பதில் போகும்.',
            'steps' => ['<b>Bot Replies</b>-ஐத் திறந்து <b>+ New rule</b>-ஐ அழுத்தவும்.', 'வாடிக்கையாளர்கள் அனுப்பும் சொற்களை உள்ளிடவும், உதா. <b>price, rate, cost</b>.', 'பதிலை எழுதுங்கள். <b>+ Customer name</b> மூலம் தனிப்பட்டதாக்குங்கள்.', 'தேவைப்பட்டால் 3 பொத்தான்கள் வரை சேர்த்துச் சேமிக்கவும்.'],
            'tips' => ['"hi / hello"-க்கு ஒரு சிறிய மெனுவுடன் விதி அமையுங்கள் — பெரும்பாலான முதல் மெசேஜ்களுக்கு அதுவே பதில் சொல்லும்.']],
        'demo-bookings' => ['t' => 'டெமோ முன்பதிவுகளைக் கையாளுங்கள்', 's' => 'WhatsApp மூலம் பதிவான சந்திப்புகளைப் பார்த்து ஒரே கிளிக்கில் உறுதிசெய்யுங்கள்.',
            'steps' => ['<b>Demo Bookings</b>-ஐத் திறக்கவும்.', 'புதிய கோரிக்கைகள் வாடிக்கையாளர் பெயர், தேதி, நேரத்துடன் வரும்.', '<b>Confirm + Notify</b>-ஐ அழுத்தினால் உறுதியாகி WhatsApp மெசேஜ் போகும்.', 'சந்திப்பு முடிந்ததும் <b>Completed</b> எனக் குறிக்கவும், அல்லது சாட்டைத் திறந்து பேசவும்.']],
        'waamini-bot' => ['t' => 'WAAMINI AI பாட்டுக்குப் பயிற்சி அளிக்கவும்', 's' => 'உங்கள் வணிகத் தகவல்களைக் கொண்டு வாடிக்கையாளர் கேள்விகளுக்குப் பதில் சொல்லும் AI உதவியாளர்.',
            'steps' => ['<b>WAAMINI Bot</b>-ஐத் திறந்து <b>Finish setup</b>-ஐ அழுத்தவும்.', '<b>Instructions</b>-இல் பாட் எப்படிப் பேச வேண்டும், எதைத் தவிர்க்க வேண்டும் என்று சொல்லுங்கள்.', '<b>Knowledge</b>-ஐத் திறந்து பொருட்கள், விலைகள், நேரங்கள், FAQ-களைச் சேர்க்கவும்.', '<b>Bot Settings</b>-இல் ஃபாலோ-அப் மெசேஜ்களையும் எப்போது நபரிடம் ஒப்படைக்க வேண்டும் என்பதையும் அமைக்கவும்.', 'Overview பக்கத்தின் சாட் பெட்டியில் சோதிக்கவும்.'],
            'tips' => ['Knowledge எவ்வளவு தெளிவாக இருக்கிறதோ, பதில்கள் அவ்வளவு சிறப்பாக இருக்கும்.', 'Chats-இல் நீங்கள் பதிலளித்த பின் <b>Resume bot</b>-ஐ அழுத்தினால் பாட் மீண்டும் பொறுப்பேற்கும்.']],
        'flow-builder' => ['t' => 'சாட்பாட் ஃப்ளோ உருவாக்கவும்', 's' => 'பொத்தான்களும் கிளைகளும் கொண்ட படிப்படியான உரையாடலை வடிவமையுங்கள் — கோடிங் தேவையில்லை.',
            'steps' => ['<b>Flow Builder</b>-ஐத் திறந்து <b>New flow</b>-ஐ அழுத்தவும்.', '<b>Triggers</b> அமைக்கவும் — ஃப்ளோவைத் தொடங்கும் சொற்கள்.', 'மெசேஜ், கேள்வி, பொத்தான் படிகளைச் சேர்த்து இணைக்கவும்.', '<b>Save</b> செய்து, போனிலிருந்து டிரிகர் சொல்லை அனுப்பிச் சோதிக்கவும்.']],
        'wa-flows' => ['t' => 'WhatsApp படிவங்கள் (Flows) உருவாக்கவும்', 's' => 'WhatsApp-க்குள்ளேயே திறக்கும் படிவங்கள் மூலம் லீட்கள், முன்பதிவுகள், கருத்துகளைச் சேகரியுங்கள்.',
            'steps' => ['<b>WhatsApp Flows</b>-ஐத் திறக்கவும்.', 'தொடக்கத்தைத் தேர்ந்தெடுக்கவும்: <b>Lead enquiry</b>, <b>Appointment</b>, <b>Feedback</b> அல்லது <b>Blank</b>.', '<b>Open in visual builder</b> மூலம் புலங்களைத் திருத்தவும்.', 'வெளியிட்டு, ஒரு டெம்ப்ளேட் பொத்தானுடன் இணைக்கவும்.'],
            'tips' => ['ஏற்கனவே Meta-வில் உருவாக்கினீர்களா? <b>Sync templates</b> மூலம் கொண்டு வாருங்கள்.']],
        'drip' => ['t' => 'தானியங்கி ஃபாலோ-அப் (ட்ரிப்)', 's' => 'புதிய லீட்களுக்குப் பல நாட்களில் தொடர் மெசேஜ்களைத் தானாக அனுப்புங்கள்.',
            'steps' => ['<b>Auto Follow-up</b>-ஐத் திறக்கவும்.', '<b>Campaign Name</b> மற்றும் <b>Trigger Condition</b>-உடன் ஒரு வரிசையை உருவாக்கவும்.', 'ஒவ்வொரு மெசேஜையும், முந்தையதற்குப் பிறகு எத்தனை நாளில் போக வேண்டும் என்பதையும் சேர்க்கவும்.', 'சேமிக்கவும். டிரிகருக்குப் பொருந்தும் புதிய தொடர்புகளுக்குத் தொடர் தானாகப் போகும்.']],
        'ocr' => ['t' => 'புகைப்படத்திலிருந்து எண்களை ஸ்கேன் செய்யவும்', 's' => 'விசிட்டிங் கார்டு அல்லது பதிவேட்டின் புகைப்படத்திலிருந்து எண்களைத் தொடர்புகளாகச் சேமிக்கவும்.',
            'steps' => ['<b>OCR Scanner</b>-ஐத் திறக்கவும்.', 'படத்தைக் கிளிக் செய்யவும் அல்லது இழுத்துவிடவும் (JPG, PNG, WEBP, 5 MB வரை).', 'முடிவுகளில் கிடைத்த எண்களைச் சரிபார்க்கவும்.', '<b>Save to CRM</b>-ஐ அழுத்தி Contacts-இல் சேர்க்கவும்.']],
        'voice' => ['t' => 'குரல் குறிப்புகளைப் பாருங்கள்', 's' => 'வாடிக்கையாளர்களின் அனைத்துக் குரல் குறிப்புகளும் ஒரே பட்டியலில், கிடைத்தால் உரையுடன்.',
            'steps' => ['<b>Voice Analyzer</b>-ஐத் திறக்கவும்.', '<b>24h</b>, <b>7d</b>, <b>30d</b> அல்லது எல்லா காலத்தையும் வைத்து வடிகட்டவும்.', 'உரை அல்லது கேப்ஷனைப் படித்து, பதிலளிக்க <b>Open chat</b>-ஐ அழுத்தவும்.']],
        'catalog' => ['t' => 'கேட்டலாக்கில் பொருட்களைச் சேர்க்கவும்', 's' => 'உங்கள் பொருட்களைப் பட்டியலிடுங்கள் — வாடிக்கையாளர்கள் WhatsApp-இல் பார்த்து ஆர்டர் செய்யலாம்.',
            'steps' => ['<b>Catalog</b>-ஐத் திறக்கவும்.', 'பெயர், விலை, புகைப்படம், விளக்கத்துடன் பொருளைச் சேர்க்கவும்.', '<b>Save Product</b>-ஐ அழுத்தவும்.', 'வாடிக்கையாளர்கள் <b>Send Enquiry</b> மூலம் கேட்கலாம்; ஆர்டர்கள் Orders-க்கு வரும்.']],
        'orders' => ['t' => 'ஆர்டர்களை நிர்வகிக்கவும்', 's' => 'ஒவ்வொரு WhatsApp ஆர்டரையும் புதியதிலிருந்து டெலிவரி வரை கண்காணிக்கவும்.',
            'steps' => ['<b>Orders</b>-ஐத் திறக்கவும்.', 'ஆர்டரைத் திறந்து பொருட்களையும் வாடிக்கையாளரையும் பாருங்கள்.', 'நிலை மாறும்போது <b>Update Status</b> செய்யுங்கள் — வாடிக்கையாளருக்கு WhatsApp அப்டேட் போகும்.', 'பணம் கிடைத்ததும் <b>Mark as Paid</b>-ஐ அழுத்தவும்.']],
        'checkout' => ['t' => 'பேமெண்ட் & செக்அவுட் அமைக்கவும்', 's' => 'பேமெண்ட் கேட்வேயை இணைத்தால் வாடிக்கையாளர்கள் WhatsApp-க்குள்ளேயே பணம் செலுத்தலாம்.',
            'steps' => ['<b>E-commerce Settings</b> → <b>Payments &amp; checkout</b>-ஐத் திறக்கவும்.', 'உங்கள் பேமெண்ட் கேட்வே keys-ஐ உள்ளிடவும்.', '<b>Copy URL</b> மூலம் வெப்ஹூக் URL-ஐ கேட்வேயில் ஒட்டவும்.', '<b>Test webhook</b> செய்து, <b>Save settings</b>-ஐ அழுத்தவும்.']],
        'sales-dashboard' => ['t' => 'விற்பனையைக் கண்காணிக்கவும்', 's' => 'வருமானம், டெலிவரியான ஆர்டர்கள், AI பாட் எவ்வளவு விற்றது என்று பாருங்கள்.',
            'steps' => ['<b>Order Dashboard</b>-ஐத் திறக்கவும்.', '<b>Last 7 days</b> வருமானத்தையும் <b>Best day</b>-ஐயும் பாருங்கள்.', '<b>Bot revenue</b>-ஐப் பாருங்கள் — AI பாட் முடித்த விற்பனை.']],
        'catalog-reports' => ['t' => 'கேட்டலாக் அறிக்கைகள்', 's' => 'வாடிக்கையாளர்கள் அதிகம் பார்க்கும், கேட்கும் பொருட்கள் எவை என்று பாருங்கள்.',
            'steps' => ['<b>Catalog Reports</b>-ஐத் திறக்கவும்.', 'தேதிகளைத் தேர்ந்தெடுத்து <b>Apply</b>-ஐ அழுத்தவும்.', '<b>Interactions per day</b> மற்றும் முன்னணிப் பொருட்களைப் பாருங்கள்.']],
        'shopify' => ['t' => 'உங்கள் Shopify ஸ்டோரை இணைக்கவும்', 's' => 'Shopify வாடிக்கையாளர்களுக்கு ஆர்டர் அப்டேட்களையும் கைவிட்ட கார்ட் நினைவூட்டல்களையும் WhatsApp-இல் அனுப்புங்கள்.',
            'steps' => ['<b>Integrations → Shopify</b>-ஐத் திறக்கவும்.', 'ஸ்டோர், ஆப் விவரங்களை உள்ளிட்டு <b>Save Shopify app</b>-ஐ அழுத்தவும்.', 'அனுப்ப வேண்டிய மெசேஜ்களைத் தேர்ந்தெடுத்து (order placed, shipped, cart reminder) <b>Save messages</b> செய்யவும்.', 'Shopify அப்டேட்களை அனுப்புகிறதா என்று <b>Re-check events</b> மூலம் உறுதிசெய்யவும்.']],
        'quotes' => ['t' => 'PDF விலைப்புள்ளிகளை அனுப்பவும்', 's' => 'உங்கள் பிராண்டுடன் விலைப்புள்ளி உருவாக்கி WhatsApp-இல் PDF-ஆகப் பகிருங்கள்.',
            'steps' => ['<b>PDF Quotations</b>-ஐத் திறக்கவும்.', '<b>Company Branding</b>-ஐ நிரப்பவும்: பெயர், லோகோ, முகவரி, GSTIN.', '<b>Bank Account Details</b> மற்றும் <b>Notes &amp; Terms</b>-ஐச் சேர்க்கவும்.', 'பொருட்களைச் சேர்த்து, முன்னோட்டம் பார்த்துச் சேமிக்கவும்.']],
        'gst' => ['t' => 'GST விலைப்பட்டியல் உருவாக்கவும்', 's' => 'GST விலைப்பட்டியல் தயாரித்து வாடிக்கையாளர்களுக்கு WhatsApp-இல் அனுப்புங்கள்.',
            'steps' => ['<b>GST Invoices</b>-ஐத் திறக்கவும்.', '<b>Quick invoice</b>-ஐ அழுத்தி வாடிக்கையாளரையும் பொருட்களையும் உள்ளிடவும்.', 'சேமித்து அனுப்பவும் — <b>Recent invoices</b>-இல் கண்காணிக்கவும்.']],
        'loyalty' => ['t' => 'லாயல்டி திட்டத்தை நடத்துங்கள்', 's' => 'ஆர்டர்களுக்குப் புள்ளிகள் கொடுத்து, மீண்டும் வாங்குபவர்களுக்கு வெகுமதி அளியுங்கள்.',
            'steps' => ['<b>Loyalty &amp; Rewards</b>-ஐத் திறந்து <b>Activate loyalty engine</b>-ஐ அழுத்தவும்.', '<b>Points per paid order</b> மற்றும் <b>Points per message sent</b>-ஐ அமைக்கவும்.', '<b>Reward threshold</b>-ஐ அமைக்கவும் — வெகுமதிக்கு எத்தனை புள்ளிகள் தேவை.', 'புள்ளிகள் சேர்க்கும் வாடிக்கையாளர்களை <b>Customers with points</b>-இல் பாருங்கள்.']],
        'ads-leads' => ['t' => 'விளம்பரங்களிலிருந்து வந்த லீட்களைப் பாருங்கள்', 's' => 'எந்த Facebook அல்லது Instagram விளம்பரத்திலிருந்து எந்த WhatsApp லீட் வந்தது என்று தெரிந்துகொள்ளுங்கள்.',
            'steps' => ['<b>Ads Leads</b>-ஐத் திறக்கவும்.', 'தேதி வரம்பைத் தேர்ந்தெடுத்து <b>Apply</b>-ஐ அழுத்தவும்.', '<b>Leads by ad</b>-ஐப் பார்த்து, ஒரு விளம்பரத்தைத் திறந்து <b>Customers from this ad</b>-ஐப் பாருங்கள்.']],
        'capi' => ['t' => 'விற்பனைத் தகவலை Meta Ads-க்கு அனுப்பவும்', 's' => 'எந்த சாட்கள் விற்பனையானது என்று Meta-வுக்குச் சொல்லுங்கள் — உங்கள் விளம்பரங்கள் அதிக வாங்குபவர்களைக் கண்டறியும்.',
            'steps' => ['<b>Conversions API</b>-ஐத் திறந்து <b>Finish setup</b>-ஐ அழுத்தவும்.', 'அனுப்ப வேண்டிய <b>Conversion Events</b>-ஐத் தேர்ந்தெடுக்கவும் (lead, purchase).', '<b>Event log</b>-ஐப் பார்த்து, தோல்வியடைந்தவற்றுக்கு <b>Retry</b> செய்யவும்.']],
        'analytics' => ['t' => 'CRM பகுப்பாய்வு', 's' => 'லீட் வளர்ச்சி, டெலிவரி செயல்திறன், பாட் உரையாடல்கள் — வரைபடங்களில்.',
            'steps' => ['<b>CRM Analytics</b>-ஐத் திறக்கவும்.', '<b>14d</b> மற்றும் <b>30d</b> இடையே மாற்றிப் பாருங்கள்.', '<b>Lead growth</b>, <b>Delivery performance</b>, <b>Health check</b>-ஐப் பாருங்கள்.']],
        'pulse' => ['t' => 'கணக்கை ஆரோக்கியமாக வைத்திருங்கள் (Pulse)', 's' => 'தோல்வியடைந்த மெசேஜ்கள் போன்ற சிக்கல்களை Pulse கண்டறிந்து சரிசெய்யும் வழியைச் சொல்லும்.',
            'steps' => ['<b>Pulse</b>-ஐத் திறக்கவும்.', 'கடந்த 14 நாட்களின் <b>Most common issues</b>-ஐப் பாருங்கள்.', 'ஒவ்வொன்றையும் சரிசெய்து <b>Mark as fixed</b>-ஐ அழுத்தவும்.']],
        'wa-health' => ['t' => 'உங்கள் எண்ணின் நிலையைச் சரிபார்க்கவும்', 's' => 'சரிபார்க்கப்பட்ட பெயர், மெசேஜிங் அடுக்கு, சமீபத்திய API செயல்பாட்டைப் பாருங்கள்.',
            'steps' => ['<b>WhatsApp Health</b>-ஐத் திறக்கவும்.', '<b>Messaging tier</b>-ஐப் பாருங்கள் — ஒரு நாளில் எத்தனை பேருக்கு மெசேஜ் அனுப்பலாம்.', '<b>Last 24 hours</b> <b>API activity</b>-ஐப் பாருங்கள்.']],
        'school-fees' => ['t' => 'பள்ளிக் கட்டண நினைவூட்டல்கள்', 's' => 'கட்டணக் கடைசி தேதியைப் பெற்றோருக்கு WhatsApp-இல் தானாக நினைவூட்டுங்கள்.',
            'steps' => ['<b>School Fees</b>-ஐத் திறந்து <b>Add student</b>-ஐ அழுத்தவும்.', 'தொகை, கடைசி தேதியுடன் <b>Add fee</b>-ஐ அழுத்தவும்.', 'கடைசி தேதிக்கு முன் பெற்றோருக்கு நினைவூட்டல் போகும் — கையால் எதுவும் செய்ய வேண்டாம்.']],
        'vehicle' => ['t' => 'வாகன சர்வீஸ் நினைவூட்டல்கள்', 's' => 'வாகன சர்வீஸ் நேரம் வரும்போது வாடிக்கையாளர்களுக்கு நினைவூட்டுங்கள்.',
            'steps' => ['<b>Vehicle Reminders</b>-ஐத் திறக்கவும்.', 'வாடிக்கையாளர், வாகன எண், அடுத்த சர்வீஸ் தேதியைச் சேர்க்கவும்.', '<b>Save vehicle</b>-ஐ அழுத்தவும் — நினைவூட்டல் சரியான நேரத்தில் போகும்.']],
        'medicine' => ['t' => 'மருந்து நினைவூட்டல்கள்', 's' => 'நோயாளிகளுக்கு மருந்து எடுக்கவும் மீண்டும் வாங்கவும் நினைவூட்டுங்கள்.',
            'steps' => ['<b>Medicine Reminders</b>-ஐத் திறந்து <b>Add reminder</b>-ஐ அழுத்தவும்.', 'நோயாளி, மருந்து, நேரங்களை உள்ளிடவும்.', 'சேமிக்கவும் — நினைவூட்டல்கள் தானாகப் போகும்.']],
        'integrations' => ['t' => 'உங்கள் மற்ற ஆப்களை இணைக்கவும்', 's' => 'IndiaMART, Facebook Lead Ads போன்ற ஆப்களிலிருந்து லீட்களைக் கொண்டு வாருங்கள்.',
            'steps' => ['<b>Integrations</b>-ஐத் திறக்கவும்.', '<b>Your integrations</b>-இல் ஆப்பைத் தேர்ந்தெடுக்கவும்.', 'அதன் படிகளை முடித்து <b>Finish setup</b>-ஐ அழுத்தவும்.']],
        'webhooks' => ['t' => 'Zapier, Pabbly & வெப்ஹூக்குகள்', 's' => 'எந்த ஆப்பிலிருந்தும் லீட்களை Waamini-க்கு, அல்லது Waamini நிகழ்வுகளை எந்த ஆப்புக்கும் அனுப்புங்கள்.',
            'steps' => ['<b>Zapier &amp; Webhooks</b>-ஐத் திறக்கவும்.', '<b>Your webhook</b> URL-ஐயும் சான்றுகளையும் நகலெடுக்கவும்.', 'அவற்றை Zapier, Pabbly அல்லது உங்கள் இணையதளப் படிவத்தில் ஒட்டவும்.', 'டெவலப்பர் உதவினால் <b>Code examples</b> (PHP, Node.js, Python) பாருங்கள்.']],
        'api' => ['t' => 'API & வெப்ஹூக் மையம்', 's' => 'உங்கள் சொந்த மென்பொருளை இணைக்க API key மற்றும் endpoints.',
            'steps' => ['<b>Settings → API</b>-ஐத் திறக்கவும்.', 'உங்கள் <b>API Key</b>-ஐ நகலெடுத்து ரகசியமாக வைத்திருங்கள்.', 'உங்கள் அமைப்புக்கு நிகழ்வுகள் வர <b>Outbound Webhook</b>-ஐ அமைக்கவும்.', '<b>Quick-start</b>-ஐப் பின்பற்றி API மூலம் முதல் மெசேஜை அனுப்புங்கள்.']],
        'gsheets' => ['t' => 'Google Sheets உடன் ஒத்திசைக்கவும்', 's' => 'லீட்களையும் விற்பனையையும் Google Sheet-இல் தானாகச் சேமியுங்கள்.',
            'steps' => ['<b>Settings → Google Sheets</b>-ஐத் திறக்கவும்.', '<b>Step 1:</b> ஸ்கிரிப்டை உங்கள் ஷீட்டில் நகலெடுக்கவும் (Extensions → Apps Script).', 'அதை <b>Web app</b>-ஆக deploy செய்து URL-ஐ நகலெடுக்கவும்.', '<b>Step 2:</b> <b>Web App URL</b>-ஐ இங்கே ஒட்டிச் சேமிக்கவும்.']],
        'gcal' => ['t' => 'Google Calendar & Meet', 's' => 'முன்பதிவுகளை Google Meet இணைப்புடன் உங்கள் காலெண்டரில் தானாகச் சேர்க்கவும்.',
            'steps' => ['<b>Google Calendar &amp; Meet</b>-ஐத் திறக்கவும்.', 'கேட்கும்போது Google மூலம் உள்நுழையவும்.', 'உறுதியான புதிய முன்பதிவுகள் Meet இணைப்புடன் காலெண்டரில் வரும்.']],
        'sales-tracker' => ['t' => 'WhatsApp மூலம் விற்பனையைப் பதிவு செய்யவும்', 's' => '"Saree, 5, 1500" போன்ற மெசேஜ் அனுப்பி விற்பனையைப் பதிவு செய்யுங்கள்.',
            'steps' => ['<b>Sales Tracker</b>-ஐத் திறந்து <b>Enable Sales Tracker</b>-ஐ இயக்கவும்.', 'விற்பனையைப் பதிவு செய்ய அனுமதிக்க வேண்டிய எண்களைச் சேர்க்கவும்.', 'உங்கள் வணிக எண்ணுக்கு <b>item, quantity, price</b> அனுப்புங்கள்.', '<b>Revenue today</b> மற்றும் இந்த மாத வருமானத்தைப் பாருங்கள், அல்லது <b>Undo last sale</b> செய்யுங்கள்.']],
        'team' => ['t' => 'குழு உறுப்பினர்களைச் சேர்க்கவும்', 's' => 'ஊழியர்களுக்குத் தனி உள்நுழைவு கொடுங்கள் — அவர்கள் சாட்களுக்குப் பதிலளிக்கலாம்.',
            'steps' => ['<b>Team Members</b>-ஐத் திறக்கவும்.', 'பெயர், மின்னஞ்சல், மொபைல் எண், கடவுச்சொல்லை உள்ளிடவும்.', 'அணுகல் நிலையைத் தேர்ந்தெடுக்கவும்: <b>Standard Member</b>, <b>Support Agent</b> அல்லது <b>Dashboard only</b>.', 'சேமிக்கவும். யாராவது விலகினால் <b>Disabled</b> செய்யவும்.']],
